SELECT 'gongkao', '家庭成员综合', 'kp-age-mp-family-mix', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "家庭成员综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "祖孙三代大杂烩。极易出现“倒推年份时某人未出生”的陷阱！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "包含了爷爷、爸爸、孙子的大跨度年龄题。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "利用人类生育常识进行排雷："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "父子年龄差一般在 22~35 之间。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "祖孙年龄差一般在 45~70 之间。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "任何倒退的年份差，绝不能大于当下最小孩子的年龄！否则孩子在那年不仅是负数，连受精卵都不是。"}]}]}]}]}$$ AS jsonb), NULL, '家庭成员综合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "家庭成员综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_mp_family_mix", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
